<h1>Categorías</h1><p>Para eliminar una categoría, primero reasigne todas sus noticias.</p><a class="button" href="<?= e(url('category-edit')) ?>">Crear categoría</a><ul class="category-list"><?php foreach ($categories as $c): ?><li><strong><?= e($c['name']) ?></strong><span><?= e($c['total']) ?> noticias</span><a href="<?= e(url('category-edit', ['id' => $c['id']])) ?>">Editar</a><a href="<?= e(url('category-delete', ['id' => $c['id']])) ?>">Eliminar</a></li><?php endforeach ?></ul>
